<template><div class="lottery"><h1>抽奖模式</h1><FluentTabs v-model="mode" :options="[{value:'prize',label:'直接抽奖',icon:'fluent:gift-24-regular'},{value:'assign',label:'先抽人再分配',icon:'fluent:people-24-regular'}]"/><FluentCard><div class="row"><FluentInput v-model="name" placeholder="奖品名称"/><FluentInput v-model="quantity" type="number" placeholder="库存"/><FluentInput v-model="weight" type="number" placeholder="概率权重"/><FluentButton @click="add">添加奖品</FluentButton></div><div v-for="p in prizes.current.prizes" :key="p.id" class="prize">{{p.name}} <span>库存 {{p.quantity}} · 权重 {{p.weight}}</span></div></FluentCard><FluentButton variant="primary" size="lg" :disabled="!prizes.current.prizes.some(p=>p.quantity>0)" @click="draw">{{mode==='assign'?'抽人并分配奖品':'开始抽奖'}}</FluentButton><h2 v-if="result">{{result}}</h2></div></template>
<script setup>import {ref,onMounted} from 'vue';import {usePrizesStore} from '../stores/prizes';import FluentTabs from '../components/FluentTabs.vue';import FluentCard from '../components/FluentCard.vue';import FluentInput from '../components/FluentInput.vue';import FluentButton from '../components/FluentButton.vue';const prizes=usePrizesStore();const mode=ref('prize'),name=ref(''),quantity=ref(1),weight=ref(1),result=ref('');onMounted(()=>prizes.initialize());function add(){if(name.value.trim()){prizes.add(name.value.trim(),quantity.value,weight.value);name.value=''}}function draw(){const p=prizes.pick();result.value=p?`${mode.value==='assign'?'已分配奖品：':'中奖：'}${p.name}`:'奖品已抽完'}</script><style scoped>.lottery{padding:32px;display:grid;gap:16px}.row{display:flex;gap:10px}.prize{padding:10px;border-bottom:1px solid var(--border-default)}.prize span{color:var(--text-muted);margin-left:12px}</style>
